import{_ as e,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Arch Linux 中啓用 Snap 支持 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中啓用 Snap 支持 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中啓用 Snap 支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中啓用 Snap 支持 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221011 How to Enable Snap Support in Arch Linux","title":"如何在 Arch Linux 中啓用 Snap 支持","tag":"202210","desc":""},"relativePath":"202210/20221011 How to Enable Snap Support in Arch Linux.md","filePath":"[post].md"}'),u={name:"202210/20221011 How to Enable Snap Support in Arch Linux.md"};function h(g,s,k,f,m,b){const n=o("Link");return d(),r("div",null,[s[32]||(s[32]=l('<h1 id="如何在-arch-linux-中啓用-snap-支持" tabindex="-1">如何在 Arch Linux 中啓用 Snap 支持 <a class="header-anchor" href="#如何在-arch-linux-中啓用-snap-支持" aria-label="Permalink to “如何在 Arch Linux 中啓用 Snap 支持”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/21/100128gzzqkf3fcg3f6q3n.jpg" alt=""></p><p>Snap 是由 Ubuntu 的母公司 Canonical 設計的通用包格式。有些人不喜歡 Snap，但它有一些優勢。</p><p>通常，某些應用僅以 Snap 格式提供。這為你提供了在 Arch Linux 中啓用 Snap 的充分理由。</p><p>我知道 AUR 擁有大量應用，但 Snap 應用通常直接來自開發人員。</p><p>如果你希望能夠在 Arch Linux 中安裝 Snap 應用，你需要先啓用 Snap 支持。</p><p>有兩種方法可以做到：</p><ul><li>使用 AUR 助手啓用 Snap 支持（更簡單）</li><li>通過從 AUR 獲取包，手動啓用 Snap 支持</li></ul><p>讓我們看看怎麼做。</p><h3 id="方法-1、使用-aur-助手啓用-snap" tabindex="-1">方法 1、使用 AUR 助手啓用 Snap <a class="header-anchor" href="#方法-1、使用-aur-助手啓用-snap" aria-label="Permalink to “方法 1、使用 AUR 助手啓用 Snap”">​</a></h3><p>Snap 支持在 Arch 用户倉庫中以 <code>snapd</code> 包的形式提供。你可以使用 AUR 助手輕鬆安裝它。</p>',11)),p("p",null,[s[2]||(s[2]=a("有 ",-1)),t(n,{href:"https://itsfoss.com/best-aur-helpers/"},{default:i(()=>[...s[0]||(s[0]=[a("許多 AUR 助手",-1)])]),_:1}),s[3]||(s[3]=a("，但 ",-1)),s[4]||(s[4]=p("code",null,"yay",-1)),s[5]||(s[5]=a(" 是我更喜歡的，因為它的語法類似於 ",-1)),t(n,{href:"https://itsfoss.com/pacman-command/"},{default:i(()=>[...s[1]||(s[1]=[a("pacman 命令",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[33]||(s[33]=l(`<p>如果你還沒有安裝 AUR，請使用以下命令安裝 Yay（需要事先安裝 <code>git</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://aur.archlinux.org/yay</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd yay</span></span>
<span class="line"><span></span></span>
<span class="line"><span>makepkg -si</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/yay-makepkg.png" alt="安裝 yay"></p><p>現在 <code>yay</code> 已安裝，你可以通過以下方式安裝 <code>snapd</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yay -Sy snapd</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/yay-install-snapd.png" alt="使用 yay 從 AUR 安裝 snapd"></p>`,6)),p("p",null,[s[8]||(s[8]=a("每當你 ",-1)),t(n,{href:"https://itsfoss.com/update-arch-linux/"},{default:i(()=>[...s[7]||(s[7]=[a("更新 Arch Linux",-1)])]),_:1}),s[9]||(s[9]=a(" 系統時，",-1)),s[10]||(s[10]=p("code",null,"yay",-1)),s[11]||(s[11]=a(" 都會啓用 ",-1)),s[12]||(s[12]=p("code",null,"snapd",-1)),s[13]||(s[13]=a(" 的自動更新。",-1))]),s[34]||(s[34]=l(`<h4 id="驗證-snap-支持是否有效" tabindex="-1">驗證 Snap 支持是否有效 <a class="header-anchor" href="#驗證-snap-支持是否有效" aria-label="Permalink to “驗證 Snap 支持是否有效”">​</a></h4><p>要測試 Snap 支持是否正常工作，請安裝並運行 <code>hello-world</code> Snap 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install hello-world</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hello-world</span></span>
<span class="line"><span>（或者）</span></span>
<span class="line"><span>sudo snap run hello-world</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snap-hello-world-1.png" alt="hello-world Snap 包執行"></p><p>如果它運行良好，那麼你可以輕鬆安裝其他 Snap 包。</p><h3 id="方法-2、從-aur-手動構建-snapd-包" tabindex="-1">方法 2、從 AUR 手動構建 snapd 包 <a class="header-anchor" href="#方法-2、從-aur-手動構建-snapd-包" aria-label="Permalink to “方法 2、從 AUR 手動構建 snapd 包”">​</a></h3><p>如果你不想使用 AUR 助手，你仍然可以從 AUR 獲取 <code>snapd</code>。讓我展示詳細的過程。</p><p>你需要先安裝一些構建工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Sy git go go-tools python-docutils</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-dependencies.png" alt="為 Snap 安裝依賴項"></p><p>完成依賴項安裝後，現在可以克隆 <code>snapd</code> 的 AUR 目錄，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://aur.archlinux.org/snapd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd snapd</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-clone.png" alt="克隆倉庫"></p><p>然後構建 <code>snapd</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>makepkg -si</span></span></code></pre></div><p>當它要求安裝其他依賴包時輸入 <code>yes</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-makepkg-800x460.png" alt="手動構建 snapd"></p><p>你已安裝 <code>snapd</code> 守護程序。但是，需要啓用它以在啓動時自動啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable snapd --now</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo systemctl enable snapd.apparmor --now #start snap applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo ln -s /var/lib/snapd/snap /snap #optional: classic snap support</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/enable-snapd-startup-2.png" alt="啓動時啓用 Snap"></p><p>手動構建包的主要缺點是每次新更新啓動時你都必須手動構建。使用 AUR 助手為我們解決了這個問題。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,22)),p("p",null,[s[15]||(s[15]=a("我更喜歡 Arch Linux 中的 pacman 和 AUR。很少能看到不在 AUR 中但以其他格式提供的應用。儘管如此，在某些你希望直接從源獲取它的情況下，使用 Snap 可能是有利的，例如 ",-1)),t(n,{href:"https://itsfoss.com/install-spotify-arch/"},{default:i(()=>[...s[14]||(s[14]=[a("在 Arch 上安裝 Spotify",-1)])]),_:1}),s[16]||(s[16]=a("。",-1))]),s[35]||(s[35]=p("p",null,"希望本教程對你有所幫助。如果你有任何問題，請告訴我。",-1)),s[36]||(s[36]=p("hr",null,null,-1)),p("p",null,[s[18]||(s[18]=a("via: ",-1)),t(n,{href:"https://itsfoss.com/install-snap-arch-linux/"},{default:i(()=>[...s[17]||(s[17]=[a("https://itsfoss.com/install-snap-arch-linux/",-1)])]),_:1})]),p("p",null,[s[23]||(s[23]=a("作者：",-1)),t(n,{href:"https://itsfoss.com/author/pranav/"},{default:i(()=>[...s[19]||(s[19]=[a("Pranav Krishna",-1)])]),_:1}),s[24]||(s[24]=a(" 選題：",-1)),t(n,{href:"https://github.com/lkxed"},{default:i(()=>[...s[20]||(s[20]=[a("lkxed",-1)])]),_:1}),s[25]||(s[25]=a(" 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[21]||(s[21]=[a("geekpi",-1)])]),_:1}),s[26]||(s[26]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[22]||(s[22]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[29]||(s[29]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[27]||(s[27]=[a("LCTT",-1)])]),_:1}),s[30]||(s[30]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[28]||(s[28]=[a("Linux中國",-1)])]),_:1}),s[31]||(s[31]=a(" 榮譽推出",-1))])])}const S=e(u,[["render",h]]);export{x as __pageData,S as default};
